#!/usr/bin/env python3
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.36.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.36.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.36.0.js').read_text()
NB=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-notebook-v5.js').read_text()
CSS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.36.0.css').read_text()

def check(ok,label):
    if not ok: raise SystemExit(f'FAIL - {label}')
    print(f'PASS - {label}')

check('Version: 0.36.0' in MAIN and "SC_WORKSPACE_VERSION', '0.36.0" in MAIN,'plugin/runtime version')
check((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.36.0','0.35.0','Notebook Synthesis & Citation Workspace'),'manifest release lineage')
check((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(32,'sc-workspace-project/17.0','sc-workspace-project-export/17.0'),'storage 32 / project 17.0 / export 17.0')
check((MAN['migration']['storage_from'],MAN['migration']['storage_to'])==(31,32),'storage 31→32 migration')
check((MAN['migration']['project_schema_from'],MAN['migration']['project_schema_to'])==('sc-workspace-project/16.0','sc-workspace-project/17.0'),'project schema 16.0→17.0')
check('function migrateV31(raw)' in JS and 'if (raw.schemaVersion === 31) return migrateV31(raw);' in JS,'browser migration runtime')
check((MAN['notebook_workspace_schema'],MAN['notebook_schema'],MAN['notebook_block_schema'],MAN['notebook_export_schema'])==('sc-workspace-notebook-workspace/5.0','sc-workspace-notebook/3.0','sc-workspace-notebook-block/3.0','sc-workspace-notebook-export/5.0'),'Notebook v5 container schemas')
check((MAN['notebook_synthesis_schema'],MAN['notebook_synthesis_export_schema'])==('sc-workspace-notebook-synthesis/1.0','sc-workspace-notebook-synthesis-export/1.0'),'Notebook synthesis schemas')
check(MAN['research_notebook']['synthesis_kinds']==['outline','citation-pack','source-matrix','evidence-summary','research-synthesis'],'five synthesis outputs')
check(MAN['research_notebook']['synthesis_requires_explicit_selection'] and MAN['research_notebook']['synthesis_uses_notebook_blocks_and_workspace_objects'],'explicit selected-material synthesis')
check(MAN['research_notebook']['citation_pack_uses_recorded_metadata_only'] and not MAN['research_notebook']['citation_guessing'],'recorded citation metadata only')
check(MAN['research_notebook']['source_matrix_retains_selected_source_context'],'source matrix context retention')
check(MAN['research_notebook']['evidence_summary_does_not_score_strength'] and MAN['research_notebook']['research_synthesis_is_reviewable_draft'],'reviewable non-scoring synthesis')
check(MAN['research_notebook']['portable_synthesis_export'] and MAN['research_notebook']['synthesis_can_materialize_document'],'portable synthesis and explicit Document materialization')
check(all(x in NB for x in ('generateSynthesis','exportSynthesis','resolveRef','synthesesForRef','SYNTHESIS_KINDS')),'synthesis helper runtime')
check(all(x in JS for x in ('renderNotebookSynthesis','notebookMetricSyntheses','data-scw-notebook-synthesis-form','notebook-synthesis-document')),'synthesis application runtime')
check(all(x in PHP for x in ('data-scw-notebook-synthesis-form','data-scw-notebook-synthesis-material','data-scw-notebook-synthesis-list','Missing citation facts remain missing')),'synthesis application surface')
check("'schema' => 'sc-workspace-project-contract/17.0'" in PHP and "'export_schema' => 'sc-workspace-project-export/17.0'" in PHP,'Project REST contract v17')
check("array('sc-workspace-project/17.0','sc-workspace-project/16.0','sc-workspace-project/15.0'" in PHP,'account persistence accepts Project v17 + legacy window')
check("'notebook_synthesis_schema' => 'sc-workspace-notebook-synthesis/1.0'" in PHP and "'citation_guessing' => false" in PHP,'Notebook REST synthesis contract')
check(not MAN['governance']['notebook_automatic_synthesis'] and not MAN['governance']['notebook_synthesis_automatic_ai'],'no automatic synthesis/AI')
check(not MAN['governance']['notebook_synthesis_citation_guessing'] and MAN['governance']['notebook_synthesis_missing_citation_facts_remain_missing'],'no citation guessing')
check(not MAN['governance']['notebook_synthesis_source_material_mutation'] and not MAN['governance']['notebook_synthesis_hidden_evidence_score'],'no source mutation or hidden evidence score')
check(MAN['migration']['preserves_notebook_promotions'] and MAN['migration']['preserves_notebook_collections'] and MAN['migration']['preserves_notebook_links'] and MAN['migration']['preserves_source_capture'],'v0.33–v0.35 notebook research state preserved')
check(MAN['canonical_library_path']=='/knowledge-libraries/' and '/knowledge-libraries/' in PHP,'canonical Knowledge Library route')
check((REG['public_version'],REG['previous_version'])==('0.36.0','0.35.0'),'registry record lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0360'" in REGPHP and 'LEGACY_PENDING_KEY_V0350' in REGPHP,'registry pending/backup lineage')
check((ROOT/'history/release-manifest-v0.35.0.json').exists() and (ROOT/'history/workspace-product-record-v0.35.0.json').exists(),'v0.35.0 history preserved')
for name in ('sc-workspace-notebook-synthesis-v1.schema.json','sc-workspace-notebook-synthesis-export-v1.schema.json','sc-workspace-notebook-workspace-v5.schema.json','sc-workspace-notebook-export-v5.schema.json','sc-workspace-project-v17.schema.json'):
    json.loads((ROOT/'schemas'/name).read_text())
check(True,'v0.36 synthesis/project schema JSON')
check('.scw-notebook-synthesis' in CSS and '.scw-notebook-synthesis-card' in CSS,'Notebook synthesis visual layer')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.36.0 — Notebook Synthesis & Citation Workspace')
